	private static SlotPlan trackClose(SlotPlan delegate, AtomicInteger closes) {
		return new SlotPlan() {
			@Override
			public RowCursor open(RowState row) throws IOException {
				RowCursor cursor = delegate.open(row);
				return new RowCursor() {
					private boolean closed;

					@Override
					public boolean next() throws IOException {
						return cursor.next();
					}

					@Override
					public void close() {
						if (!closed) {
							closed = true;
							closes.incrementAndGet();
							cursor.close();
						}
					}
				};
			}

			@Override
			public long producedMask() {
				return delegate.producedMask();
			}
		};
	}

	private static boolean hasOptionalSpill(Path path) throws IOException {
		return RecordingFile.readAllEvents(path)
				.stream()
				.anyMatch(event -> event.getEventType().getName().equals("org.eclipse.rdf4j.lmdb.NativeExecutionPhase")
						&& event.getString("phase").equals("spill") && event.getStackTrace() != null
						&& event.getStackTrace().getFrames().stream().anyMatch(frame -> {
							String type = frame.getMethod().getType().getName();
							String index = "org.eclipse.rdf4j.sail.lmdb.evaluation.OptionalCompatibilityIndex";
							return type.equals(NativeResultReplay.class.getName()) || type.equals(index)
									|| type.startsWith(index + "$");
						}));
	}

	private static final class OptionalOccurrence implements AutoCloseable {
		private final OptionalEvaluationIdentity identity;
		private final OptionalEvaluationIdentity.Activation activation;
		private final OptionalRhsContract contract = OptionalRhsContract.unknown();

		OptionalOccurrence(OptionalMaterialization registry) {
			identity = registry.child(registry.root());
			activation = identity.activate();
		}

		LexicalLeftJoinCursor open(SlotPlan left, SlotPlan right, int[] sharedSlots, RowState row)
				throws IOException {
			return new LexicalLeftJoinCursor(left, right, sharedSlots, null, contract, row);
		}

		@Override
		public void close() {
			try {
				activation.close();
			} finally {
				identity.close();
			}
		}
	}
